import{_ as o,o as a,c as t,a2 as l}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Goals & Objectives — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"goals-02-how-tos-and-workflows.md","filePath":"goals-02-how-tos-and-workflows.md"}'),i={name:"goals-02-how-tos-and-workflows.md"};function n(r,e,s,h,c,d){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="goals-objectives-—-how-tos-workflows" tabindex="-1">Goals &amp; Objectives — How-tos &amp; Workflows <a class="header-anchor" href="#goals-objectives-—-how-tos-workflows" aria-label="Permalink to &quot;Goals &amp; Objectives — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Goals &amp; Objectives workflows</em></p><hr><h2 id="creating-a-goal" tabindex="-1">Creating a Goal <a class="header-anchor" href="#creating-a-goal" aria-label="Permalink to &quot;Creating a Goal&quot;">​</a></h2><ol><li>Navigate to <strong>Goals &amp; Objectives</strong> from the left-hand navigation.</li><li>Click <strong>+ New Goal</strong>.</li><li>Enter a Goal name. This is the only required field.</li><li>Optionally add a description to provide context for what the Goal represents.</li><li>Click <strong>Create</strong>. The Goal appears in the list immediately.</li></ol><p>Goals are created in a flat list — there is no nesting or hierarchy within the Goals module itself.</p><hr><h2 id="editing-a-goal" tabindex="-1">Editing a Goal <a class="header-anchor" href="#editing-a-goal" aria-label="Permalink to &quot;Editing a Goal&quot;">​</a></h2><p>Goals can be edited inline, directly from the list.</p><p><strong>To edit the name:</strong></p><ol><li>Click the Goal&#39;s name in the list. It becomes an editable text field.</li><li>Type your changes.</li><li>Press Enter or click elsewhere to save.</li></ol><p><strong>To edit the description:</strong></p><ol><li>Click the description text (or the &quot;Add description…&quot; placeholder if empty).</li><li>Type your changes in the text area that appears.</li><li>Press Enter or click elsewhere to save.</li></ol><p>Press Escape at any point to cancel your changes and revert to the previous value.</p><hr><h2 id="viewing-connected-work-for-a-goal" tabindex="-1">Viewing Connected Work for a Goal <a class="header-anchor" href="#viewing-connected-work-for-a-goal" aria-label="Permalink to &quot;Viewing Connected Work for a Goal&quot;">​</a></h2><p>When a Goal has at least one object, roadmap, release, or strategy connected to it, a chevron icon appears at the left edge of its row.</p><ol><li>Click the chevron to expand the Goal row.</li><li>The downstream view opens below the Goal, showing connected work grouped by type: Objects, Roadmaps, Releases, and Strategies.</li><li>Click any entry to navigate directly to that item.</li><li>Click the chevron again to collapse.</li></ol><p>If no chevron appears, the Goal has no connected work yet. Once you link objects to the Goal (from the Backlog object detail page) or include those objects in a roadmap or release, the chevron will appear.</p><hr><h2 id="deleting-a-goal" tabindex="-1">Deleting a Goal <a class="header-anchor" href="#deleting-a-goal" aria-label="Permalink to &quot;Deleting a Goal&quot;">​</a></h2><p>Deleting a Goal requires a deliberate confirmation because it can affect other objects.</p><ol><li>Hover over the Goal row to reveal the delete icon (trash can) at the right edge.</li><li>Click the trash icon. A confirmation dialog appears.</li><li>The dialog shows the Goal&#39;s name and a summary of connected work — any Strategies, Roadmaps, or Releases that include objects linked to this Goal.</li><li>If the Goal has child objects, the dialog notes how many objects will be <strong>orphaned</strong> — they remain in the Backlog as top-level items rather than being deleted.</li><li>Confirm deletion. The Goal is permanently removed.</li></ol><blockquote><p><strong>Important:</strong> Deleting a Goal does not delete the objects linked to it. Child objects are orphaned — they remain in the Backlog but lose their parent connection. There is no undo.</p></blockquote><hr><h2 id="linking-an-object-to-a-goal" tabindex="-1">Linking an Object to a Goal <a class="header-anchor" href="#linking-an-object-to-a-goal" aria-label="Permalink to &quot;Linking an Object to a Goal&quot;">​</a></h2><p>Goals gain connected work through the Backlog, not the other way around. To link an existing object to a Goal:</p><ol><li>Open the Backlog and click on the object you want to connect.</li><li>In the object detail sidebar, find the <strong>Parents</strong> field.</li><li>Use the search picker to find and select the Goal.</li><li>The Goal now appears as a parent of that object. The downstream view on the Goal will update to reflect the connection.</li></ol><p>See the Backlog how-tos guide for more detail on the Parents field.</p><hr><p><em>Next: Advanced &amp; Customization — how the top-tier type powers Goals, downstream connection mechanics, and working at scale.</em></p>',31)])])}const m=o(i,[["render",n]]);export{g as __pageData,m as default};
